/** Registra a composição atual da arena sem modificar código, física ou artes de produção. */
import fs from 'node:fs/promises';
import assert from 'node:assert/strict';
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
const cdp='http://127.0.0.1:9222',host='http://127.0.0.1:3000';
const tab=await(await fetch(cdp+'/json/new?'+encodeURIComponent(host),{method:'PUT'})).json();
const ws=new WebSocket(tab.webSocketDebuggerUrl);await new Promise(r=>ws.addEventListener('open',r,{once:true}));
let sequence=0;const pending=new Map();
ws.addEventListener('message',e=>{const m=JSON.parse(e.data);const p=pending.get(m.id);if(p){pending.delete(m.id);m.error?p.reject(Error(m.error.message)):p.resolve(m.result);}});
const send=(method,params={})=>new Promise((resolve,reject)=>{const id=++sequence;pending.set(id,{resolve,reject});ws.send(JSON.stringify({id,method,params}));});
const run=async expression=>{const r=await send('Runtime.evaluate',{expression,awaitPromise:true,returnByValue:true});if(r.exceptionDetails)throw Error(r.exceptionDetails.exception?.description||r.exceptionDetails.text);return r.result.value;};
const until=async(expression)=>{const end=Date.now()+30000;while(Date.now()<end){if(await run(expression))return;await sleep(80);}throw Error('Não ficou pronto: '+expression);};
const folder='docs/diario-ia/qa-resultados/especial-arena';await fs.mkdir(folder,{recursive:true});
async function capture(name,data=null){
 const bytes=data?Buffer.from(data.split(',')[1],'base64'):Buffer.from((await send('Page.captureScreenshot',{format:'png'})).data,'base64');
 await fs.writeFile(folder+'/'+name+'.png',bytes);await fs.writeFile('/tmp/legendgirl-'+name+'.png',bytes);
}
try{
 await send('Page.enable');await send('Runtime.enable');await send('Emulation.setDeviceMetricsOverride',{width:1440,height:900,deviceScaleFactor:1,mobile:false});
 await send('Page.navigate',{url:host});await until('Boolean(window.game)');await run('game.assetsReady');assert.equal(await run('location.origin'),host,'Servidor temporário isolado');assert.ok(!host.endsWith(':3000'),'Porta adaptada pelo executor');
 await run(`(()=>{game.startDebugPhase('arena');game.setPaused(true);document.getElementById('start-overlay').style.display='none';})()`);
 await run(`Promise.all([game.state.toyRoomInstance.instance.arena.readyPromise,game.state.toyRoomInstance.instance.battle.readyPromise])`);
 await run(`(()=>{window.r=game.state.toyRoomInstance.instance;r.arena.state.status='COMBAT';r.battle.activate();r.battle.state.transition=null;r.introAlpha=0;r.introBannerTimer=0;})()`);

 await run(`r.isInputEnabled=()=>true`);
 const prepare=async index=>run(`(()=>{const s=r.battle.state;s.history=[];s.mode='BATTLE';s.index=${index};r.battle.spawn();s.transition=null;s.specialUsed=false;s.specialAttack=null;s.attackTime=0;s.playerHitTime=0;s.jump=0;s.player.hp=3;r.player.x=430;for(let i=0;i<240;i++)r.arena.camera.update(1,r.player,s.enemy,0);})()`);
 for(const [name,width,height,mobile] of [['desktop',1440,900,false],['retrato',390,844,true],['paisagem',844,390,true]]) {
  await send('Emulation.setDeviceMetricsOverride',{width,height,deviceScaleFactor:1,mobile});await sleep(150);
  await run(`r.mobilePresentation=${mobile};r.isTouchDevice=${mobile}`);
  await prepare(3);
  if(!mobile){
   await send('Input.dispatchKeyEvent',{type:'keyDown',code:'KeyR',key:'r',windowsVirtualKeyCode:82});
   await send('Input.dispatchKeyEvent',{type:'keyUp',code:'KeyR',key:'r',windowsVirtualKeyCode:82});
  }else{
   const point=await run(`(async()=>{const {getMobileUILayout,arenaMobileControlsLayout}=await import('./src/js/ui/MobileUILayout.js');const l=getMobileUILayout(r.canvas),b=arenaMobileControlsLayout(l).special,rect=r.canvas.getBoundingClientRect();return {x:rect.left+b.x*rect.width/r.canvas.width,y:rect.top+b.y*rect.height/r.canvas.height};})()`);
   await send('Input.dispatchTouchEvent',{type:'touchStart',touchPoints:[{x:point.x,y:point.y}]});
   await send('Input.dispatchTouchEvent',{type:'touchEnd',touchPoints:[]});
  }
  assert.equal(await run('Boolean(r.battle.state.specialAttack)'),true,'Entrada real: '+name);
  let age=0;
  for(const target of [60,88,106,118,156]){
   await run(`(()=>{for(let i=${age};i<${target};i++)r.arena.update(1);r.render();})()`);age=target;
   assert.equal(await run(`(()=>{const before=JSON.stringify(r.battle.snapshot());r.render();return before===JSON.stringify(r.battle.snapshot());})()`),true,'Desenho puro');
   if([60,106,118].includes(target))await capture('especial-'+name+'-'+target);
   if(target===106){
    assert.equal(await run(`(()=>{const save=r.snapshot();r.restore(save);return r.battle.state.specialUsed&&r.battle.state.specialAttack.elapsed===106;})()`),true,'Restore durante raio');
   }
   assert.equal(await run('r.battle.state.enemy.hp'),target<118?8:1,'Dano somente na chegada: '+name+'-'+target);
   if(target<156)assert.equal(await run('r.battle.state.specialAttack.elapsed'),target,'Relógio preparado: '+name); 
  }
  assert.equal(await run('r.arena.special()'),false,'Uso único');
  assert.equal(await run("r.battle.state.history.filter(e=>e.event==='SPECIAL_HIT').length"),1);
 }
 await prepare(0);assert.equal(await run('r.arena.special()'),true);
 await run('for(let i=0;i<156;i++)r.arena.update(1)');assert.equal(await run('r.battle.state.enemy.hp'),0);
 await run('for(let i=0;i<210;i++)r.arena.update(1)');
 assert.equal(await run('r.battle.state.index'),1);assert.equal(await run('r.arena.special()'),false,'Troca de oponente conserva uso');
 await prepare(3);
 assert.equal(await run(`(()=>{const original=navigator.getGamepads;Object.defineProperty(navigator,'getGamepads',{configurable:true,value:()=>[{index:0,mapping:'standard',buttons:Array.from({length:16},(_,i)=>({pressed:i===3,value:i===3?1:0})),axes:[0,0]}]});r.pollGamepad();Object.defineProperty(navigator,'getGamepads',{configurable:true,value:original});return Boolean(r.battle.state.specialAttack);})()`),true,'Gamepad Y preparado');
 console.log('APROVADO: teclado R e touch nativos, Y com gamepad preparado, zoom/corte/raio em três formatos, dano, troca de inimigo, save durante disparo e renderização pura. Nove capturas temporárias.');
}finally{ws.close();await fetch(cdp+'/json/close/'+tab.id);}
